import genesis as gs

gs.init()

scene = gs.Scene(
    sim_options=gs.options.SimOptions(
        dt=0.01,
        gravity=[0, 0, -9.81],
    ),
)

drone = scene.add_entity(
    gs.morphs.Drone(
        file="urdf/drones/cf2x.urdf",
        model="CF2X",
    ),
)

scene.build()

# Take off: ascend at 1 m/s until reaching 1.5 m, then hover
for _ in range(500):
    pos = drone.get_position()
    if pos[2] < 1.5:
        drone.set_velocity([0, 0, 1.0])
    else:
        drone.set_velocity([0, 0, 0])
    scene.step()

import genesis as gs

def main():
    gs.init()

    scene = gs.Scene(
        viewer_options=gs.options.ViewerOptions(
            camera_pos=(3.5, 0.0, 2.5),
            camera_lookat=(0.0, 0.0, 0.5),
        ),
        show_viewer=True,
    )

    # flat ground
    plane = scene.add_entity(
        morph=gs.options.morphs.Plane(),
    )

    # red rigid sphere
    sphere = scene.add_entity(
        morph=gs.options.morphs.Sphere(
            pos=(0.0, 0.0, 2.0),
            radius=0.2,
        ),
        material=gs.materials.Rigid(),
        surface=gs.options.surfaces.Rough(
            texture=gs.options.textures.ColorTexture(color=(1.0, 0.0, 0.0, 1.0)),
        ),
    )

    scene.build()

    for _ in range(200):
        scene.step()

if __name__ == "__main__":
    main()

